const rawNome = $input.first().json.output.nome.trim();

const isName = /^[a-zA-ZÀ-ÿ\s.'-]+$/.test(rawNome);
const isFullName = /^\S+\s+\S+/.test(rawNome);

let msgError = "";
if (!isName && rawNome === '###') {
  msgError = "Identifiquei que você não enviou o seu nome de fato. Por favor, peço que envie seu nome completo para iniciarmos seu atendimento."
}
else if (!isName) {
  msgError = "O nome que você informou contém caracteres inválidos como números, pontuações etc. Por favor, peço que envie um nome real sem nenhum caractere especial."
}
else if (!isFullName) {
  msgError = "Identifiquei que você enviou apenas o primeiro nome. Por favor, peço que envie o seu nome completo."
}

const isValid = isName && isFullName;

return [{
  json: {
    is_valido: isValid,
    nome: isValid ? rawNome : null,
    msgErro: isValid ? null : msgError
  }
}]

const rawTelefone = $input.first().json.output.telefone.trim();
const isValid = /^\(?[1-9]{2}\)?\s?9[0-9]{4}-?[0-9]{4}$/.test(rawTelefone);

let telefone = null;
if (isValid) {
  const numbers = rawTelefone.replace(/\D/g, "");
  telefone = numbers.replace(/^([0-9]{2})([0-9]{5})([0-9]{4})$/, "($1) $2-$3");
}

return [{
  json: {
    is_valido: isValid,
    telefone: isValid ? telefone : null
  }
}]

