const res = $input.first().json;

const profissionais = Array.isArray(res.profissionais)
  ? res.profissionais
  : [];

const conversa = $('[GET] Dados Conversa').first().json;
const chatId = conversa.chat_id ?? conversa.chatId;

if (!chatId) {
  throw new Error('chat_id não encontrado nos dados da conversa.');
}

const botoes = profissionais.map((profissional) => {
  const especialidade = profissional.especialidade?.nome;

  return {
    text: especialidade
      ? `${profissional.nomeExibicao} — ${especialidade}`
      : profissional.nomeExibicao,
    callback_data: `prof:${profissional.profissionalUuid}`,
  };
});

const saida = {
  chat_id: String(chatId),
  text: botoes.length
    ? 'Escolha o profissional:'
    : 'Não há profissionais disponíveis no momento.',
};

if (botoes.length) {
  saida.reply_markup = {
    // Um profissional por linha
    inline_keyboard: botoes.map((botao) => [botao]),
  };
}

return [{ json: saida }];

